# =====================================================================
#  government.map - phishing phrases for the public sector
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake ministry / agency letters behind a link, court
#           summons and hearings, fines and penalties (traffic, admin),
#           e-government portal accounts (gov.uk, myGov, e-Devlet,
#           Gosuslugi, Diia, e-gov.az / ASAN), police and prosecutor
#           notices, official document requests, public procurement
#           and tender lures
#
#  Avoided: official newsletters, meeting invitations, circulars and
#           press releases, because public bodies send real ones daily.
# =====================================================================

# ===== English =====
# Official letters
/(view|download|open|read)\s+(the\s+)?(official\s+)?(letter|notice|document|decree|order)\s+(from\s+the\s+)?(ministry|government|agency|authority|department)\s+(here|online|via\s+(the\s+)?link)/i
/(official|urgent)\s+(government|ministry)\s+(notice|notification|letter)\s+(requires|awaiting)\s+(your\s+)?(response|action|signature)/i
# Courts
/(summoned|subpoenaed|required)\s+(to\s+appear\s+)?(to|before|in|at)\s+(the\s+)?court/i
/court\s+(summons|hearing|order|notice)\s+(#?\S+\s+)?(attached|issued|scheduled|available\s+online|view)/i
/(lawsuit|legal\s+action|case)\s+(has\s+been\s+)?(filed|initiated|opened)\s+against\s+(you|your\s+(company|organization))/i
# Fines
/(traffic|speeding|parking|administrative)\s+(fine|violation|penalty|ticket)\s+(is\s+)?(unpaid|overdue|pending|outstanding|must\s+be\s+paid)/i
/pay\s+(your\s+|the\s+)?(fine|penalty)\s+(online\s+)?(within|before|to\s+avoid)/i
/(penalty|fine)\s+(notice|notification)\s+#?\S+\s+(view|pay|details)/i
# E-government accounts
/(gov\.uk|mygov|login\.gov|e-?devlet|gosuslugi|госуслуги|diia|e-?gov|asan\s+(imza|login))\s+(account\s+)?(suspended|verification|update\s+required|locked|blocked)/i
/(verify|update|confirm)\s+your\s+(identity|details)\s+on\s+the\s+(government|e-?government|national)\s+portal/i
# Police / prosecutor
/(police|prosecutor|investigation)\s+(notice|summons|report)\s+(regarding|against|concerning)\s+(you|your)/i
/(cybercrime|financial\s+crimes?)\s+(unit|department)\s+(notice|investigation|summons)/i
# Official requests
/(submit|upload|provide)\s+(the\s+)?(required|requested)\s+(official\s+)?documents?\s+(via|through|on)\s+(the\s+)?(portal|link)\s+(within|before|by)/i
# Procurement / tenders
/(public\s+)?(tender|procurement)\s+(invitation|documents?|notice)\s+(available|download|via\s+(the\s+)?link|access\s+here)/i
/(supplier|vendor)\s+(registration|accreditation)\s+(for\s+)?(government|public)\s+(tenders?|procurement)\s+(expires|required|pending)/i

